CREATE TABLE IF NOT EXISTS npc_spawn_points (
    npc_template_id  INTEGER NOT NULL
  , pos_x            INTEGER NOT NULL
  , pos_y            INTEGER NOT NULL
  , pos_z            INTEGER NOT NULL
  , orientation      INTEGER NOT NULL CHECK (0 <= orientation AND orientation <= 65535)
  , chance_percent   INTEGER          CHECK (chance_percent   IS NULL OR chance_percent   >= 0)
  , respawn_duration INTEGER          CHECK (respawn_duration IS NULL OR respawn_duration >= 0)
  , respawn_window   INTEGER          CHECK (respawn_window   IS NULL OR respawn_window   >= 0)
  , FOREIGN KEY (npc_template_id) REFERENCES npc_templates (id) ON DELETE CASCADE
);

